with src as (
  select * from jsonb_to_recordset($q$[{"topic":"Forces","subtopic":"Scalars, vectors, weight and resultant forces","spec_ref":"4.5.1.3-4.5.1.4, 4.5.6.2.2","command_word":"calculate","difficulty":"foundation","total_marks":7,"question_text":"A crate of mass 40 kg is on a horizontal floor. A worker pushes the crate with a horizontal force of 150 N. The friction force on the crate is 70 N.\n\n(a) Calculate the weight of the crate. Show your working. (2 marks)\n\n(b) Give the resultant force on the crate. (1 mark)\n\n(c) Calculate the acceleration of the crate. Show your working. (2 marks)\n\n(d) Two forces act on a different object: 30 N to the east and 40 N to the north. Determine the size of the resultant force on the object. Show your working. (2 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) W = mg = 40 × 9.8","(a) 392 N","(b) 80 N (in the direction of the push)","(c) a = F ÷ m = 80 ÷ 40","(c) 2.0 m/s²","(d) Pythagoras (√(30² + 40²)) or an accurate scale drawing","(d) 50 N"],"guidance":"In (d), 50 N from a correct scale drawing scores both marks if the drawing is described. Allow an error carried forward from an earlier part. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":4},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":1},{"topic":"Forces","subtopic":"Forces and elasticity","spec_ref":"4.5.3","command_word":"describe","difficulty":"foundation","total_marks":6,"question_text":"A student wants to investigate how the extension of a spring depends on the force applied to it. She has a spring, a clamp stand, a metre rule, a set of 1 N weights on a hanger and a pointer that can be attached to the bottom of the spring.\n\nDescribe a method the student could use. Include how she should process her results to find the relationship between force and extension.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A clear, logically ordered method that would produce valid results, including how extension is measured accurately and how the results are processed (graph) to show the relationship."},{"level":2,"marks":[3,4],"descriptor":"A method with most of the key steps that could produce results, with some idea of how to process them."},{"level":1,"marks":[1,2],"descriptor":"Some relevant steps, but the method would not produce valid results."}],"indicative":["Hang the spring from the clamp, with the metre rule clamped vertically beside it","Measure the original (unstretched) length of the spring, using the pointer on the rule","Add a weight to the hanger and measure the new length","Read the rule at eye level to avoid parallax error","Extension = new length − original length","Repeat, adding one weight at a time (e.g. up to 6 N)","Take the readings again as weights are removed, or repeat and find a mean","Plot a graph of force (y-axis) against extension (x-axis)","A straight line through the origin shows extension is directly proportional to force (up to the limit of proportionality)","The gradient gives the spring constant","Safety: wear eye protection / avoid standing under the weights"],"guidance":"Level 3 needs extension calculated correctly from lengths and a graph used to find the relationship."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":2},{"topic":"Forces","subtopic":"Forces and elasticity","spec_ref":"4.5.3","command_word":"calculate","difficulty":"higher","total_marks":4,"question_text":"A spring stretches by 0.050 m when a force of 4.0 N is applied. The spring does not go past its limit of proportionality.\n\nelastic potential energy = 0.5 × spring constant × (extension)²\n\n(a) Calculate the spring constant. Show your working. (2 marks)\n\n(b) Calculate the elastic potential energy stored in the spring. Show your working. (2 marks)","marking_style":"points","scheme":{"max":4,"points":["(a) k = F ÷ e = 4.0 ÷ 0.050","(a) 80 N/m","(b) Ee = 0.5 × 80 × 0.050²","(b) 0.10 J"],"guidance":"In (b), allow error carried forward from (a). Allow ½Fe = 0.5 × 4.0 × 0.050 = 0.10 J. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":1,"AO2":3},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":3},{"topic":"Forces","subtopic":"Pressure in fluids","spec_ref":"4.5.5.1","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"This question is about pressure in water.\n\nDensity of water = 1000 kg/m³\npressure due to a column of liquid = height of column × density of liquid × gravitational field strength\n\n(a) Calculate the pressure due to the water on a diver 12 m below the surface. Show your working. (2 marks)\n\n(b) Explain why the pressure in a liquid increases with depth. (2 marks)\n\n(c) Explain why an object under water has an upward force (upthrust) on it. (2 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) p = hρg = 12 × 1000 × 9.8","(a) 117 600 Pa (1.2 × 10⁵ Pa)","(b) The deeper you go, the greater the height (column) of water above","(b) So the weight of water pushing down on each unit area is greater","(c) The bottom surface of the object is deeper than the top surface, so the pressure on the bottom is greater","(c) This gives a bigger force upwards on the bottom than downwards on the top, so there is a resultant upward force"],"guidance":"Answers about atmospheric pressure alone do not score in (b). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":3},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":4},{"topic":"Forces","subtopic":"Describing motion: speed, velocity, acceleration and graphs","spec_ref":"4.5.6.1.5","command_word":"calculate","difficulty":"higher","total_marks":8,"question_text":"A car starts from rest and accelerates uniformly to 18 m/s in 6.0 s. It then travels at a constant 18 m/s for 10 s. It then decelerates uniformly to rest in 4.0 s.\n\n(a) Calculate the acceleration of the car in the first 6.0 s. Show your working. (2 marks)\n\n(b) Sketch (or describe) the velocity–time graph for the journey and use it to calculate the total distance travelled by the car. Show your working. (3 marks)\n\n(c) A ball is dropped from rest and falls 1.8 m to the ground. Air resistance can be ignored.\n\n(final velocity)² − (initial velocity)² = 2 × acceleration × distance\n\nCalculate the speed of the ball when it hits the ground. Show your working. (3 marks)","marking_style":"points","scheme":{"max":8,"points":["(a) a = Δv ÷ t = 18 ÷ 6.0","(a) 3.0 m/s²","(b) Distance is the area under the velocity–time graph","(b) At least one section correct: ½ × 6 × 18 = 54 m, or 18 × 10 = 180 m, or ½ × 4 × 18 = 36 m","(b) 270 m","(c) v² = 0² + 2 × 9.8 × 1.8","(c) v² = 35.28","(c) 5.9 m/s"],"guidance":"In (b), the graph itself is not marked; marks are for the distance. In (c), allow 5.94 m/s. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO2":6},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":5},{"topic":"Forces","subtopic":"Newton's laws of motion","spec_ref":"4.5.6.2.1-4.5.6.2.2, 4.5.6.1.5","command_word":"explain","difficulty":"higher","total_marks":6,"question_text":"A skydiver jumps from a plane. After some time, she opens her parachute and later lands on the ground.\n\nExplain the motion of the skydiver from the moment she jumps until just before she lands. Answer in terms of the forces acting on her.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A detailed, logically ordered explanation of all stages of the fall, linking the changes in velocity to the size of the resultant force at each stage, including both terminal velocities."},{"level":2,"marks":[3,4],"descriptor":"An explanation of at least two stages, with some link between forces and motion."},{"level":1,"marks":[1,2],"descriptor":"Simple statements about the forces or the motion, with little linking."}],"indicative":["At first she accelerates downwards at about 9.8 m/s², because the only significant force is her weight","As her speed increases, air resistance (drag) increases","So the resultant force decreases and her acceleration decreases","Eventually air resistance equals her weight; the resultant force is zero","So she travels at a constant (terminal) velocity","When the parachute opens, the surface area increases, so air resistance increases a lot","Air resistance is now greater than her weight, so the resultant force is upwards and she decelerates","As she slows, air resistance decreases until it equals her weight again","She reaches a new, lower terminal velocity, which is safe for landing"],"guidance":"Level 3 needs both terminal velocities explained in terms of balanced forces."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":6},{"topic":"Forces","subtopic":"Stopping distances","spec_ref":"4.5.6.3.1-4.5.6.3.4, 4.5.2","command_word":"calculate","difficulty":"higher","total_marks":8,"question_text":"This question is about the stopping distance of a car.\n\n(a) The stopping distance of a car is the sum of two other distances. Name them. (1 mark)\n\n(b) A car is travelling at 20 m/s. The driver's reaction time is 0.70 s. Calculate the thinking distance. Show your working. (2 marks)\n\n(c) The car has a mass of 1200 kg. When the brakes are applied, a constant braking force of 6000 N acts on the car. Calculate the braking distance. Show your working. (3 marks)\n\n(d) Give two factors, other than speed, that would increase the braking distance of the car. (2 marks)","marking_style":"points","scheme":{"max":8,"points":["(a) Thinking distance and braking distance","(b) s = vt = 20 × 0.70","(b) 14 m","(c) Kinetic energy of the car = ½ × 1200 × 20² = 240 000 J","(c) Work done by the brakes = kinetic energy: 6000 × d = 240 000","(c) d = 40 m","(d) One valid factor, e.g. wet or icy road / worn tyres / worn brakes","(d) A second valid factor, e.g. a heavier car (more mass/passengers) / a downhill slope"],"guidance":"In (c), allow a = F ÷ m = 5.0 m/s² then v² = 2as for the method. In (d), do not accept tiredness, alcohol or distractions (these affect thinking distance). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":5},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":7},{"topic":"Forces","subtopic":"Momentum","spec_ref":"4.5.7.1-4.5.7.3","command_word":"explain","difficulty":"higher","total_marks":7,"question_text":"This question is about momentum.\n\n(a) Trolley A has a mass of 2.0 kg and moves at 3.0 m/s towards trolley B, which is stationary. Trolley B has a mass of 1.0 kg.\n\n(i) Calculate the momentum of trolley A before the collision. Show your working. (2 marks)\n(ii) After the collision the trolleys stick together. Calculate their velocity after the collision. Show your working. (2 marks)\n\n(b) Explain how an air bag reduces the risk of injury to a driver in a crash. Use ideas about momentum. (3 marks)","marking_style":"points","scheme":{"max":7,"points":["(a)(i) p = mv = 2.0 × 3.0","(a)(i) 6.0 kg m/s","(a)(ii) Momentum is conserved: total momentum after = 6.0 kg m/s, total mass = 3.0 kg","(a)(ii) v = 6.0 ÷ 3.0 = 2.0 m/s","(b) The air bag increases the time taken for the driver's momentum to change (to zero)","(b) So the rate of change of momentum is smaller","(b) So the force on the driver is smaller (force = rate of change of momentum)"],"guidance":"In (b), 'cushions the driver' or 'soft' alone scores 0. Allow 'increases the time to stop, so the deceleration is smaller' for the second mark. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":4},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":8},{"topic":"Waves","subtopic":"Transverse and longitudinal waves and the wave equation","spec_ref":"4.6.1.1-4.6.1.2, 4.6.1.5","command_word":"calculate","difficulty":"higher","total_marks":8,"question_text":"This question is about waves.\n\n(a) Describe the difference between transverse and longitudinal waves. (2 marks)\n\n(b) In a ripple tank, 12 waves pass a point in 4.0 s. The wavelength of the waves is 1.5 cm. Calculate the speed of the waves in m/s. Show your working. (3 marks)\n\n(c) A pulse of ultrasound is sent into the body. It reflects from the boundary between two tissues. The echo is detected 8.0 × 10⁻⁵ s after the pulse was sent. The speed of ultrasound in the body is 1500 m/s. Calculate how far the boundary is below the skin. Show your working. (3 marks)","marking_style":"points","scheme":{"max":8,"points":["(a) In transverse waves the oscillations (vibrations) are perpendicular to the direction of energy transfer","(a) In longitudinal waves the oscillations are parallel to the direction of energy transfer","(b) f = 12 ÷ 4.0 = 3.0 Hz","(b) v = fλ = 3.0 × 0.015","(b) 0.045 m/s","(c) distance = speed × time = 1500 × 8.0 × 10⁻⁵ = 0.12 m","(c) The pulse travels there and back, so divide by 2","(c) 0.060 m (6.0 cm)"],"guidance":"In (b), 4.5 m/s (wavelength not converted) loses the answer mark only. In (c), 0.12 m scores 1. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":5},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":9},{"topic":"Waves","subtopic":"Electromagnetic waves: properties, uses and hazards","spec_ref":"4.6.2.1-4.6.2.4","command_word":"explain","difficulty":"higher","total_marks":8,"question_text":"This question is about electromagnetic waves.\n\n(a) Name the type of electromagnetic wave used:\n(i) to make images of broken bones (1 mark)\n(ii) in thermal imaging cameras (1 mark)\n\n(b) Explain why too much exposure to ultraviolet radiation is harmful. (2 marks)\n\n(c) Explain how radio waves produce a signal in the aerial of a radio receiver. (2 marks)\n\n(d) A ray of light passes at an angle from air into a glass block. Explain why the ray changes direction. (2 marks)","marking_style":"points","scheme":{"max":8,"points":["(a)(i) X-rays","(a)(ii) Infrared","(b) Ultraviolet has a high frequency, so it carries more energy (it is ionising)","(b) It can damage skin cells: cause sunburn, premature ageing of the skin or increase the risk of skin cancer","(c) The radio waves are absorbed by the aerial and make the electrons in it oscillate","(c) This produces an alternating current with the same frequency as the radio wave","(d) Light travels more slowly in glass than in air","(d) The side of the wavefront that enters the glass first slows down first, so the wave changes direction (bends towards the normal)"],"guidance":"In (b), 'causes cancer' alone scores 1."},"ao_marks":{"AO1":6,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":10},{"topic":"Waves","subtopic":"Lenses","spec_ref":"4.6.2.5-4.6.2.6","command_word":"explain","difficulty":"foundation","total_marks":6,"question_text":"This question is about lenses and colour.\n\n(a) A convex lens is used to form an image of an object. The object is 2.0 cm tall and the image is 5.0 cm tall. Calculate the magnification. (2 marks)\n\n(b) The image can be projected onto a screen. What type of image is it? (1 mark)\n\n(c) A shirt looks red in white light. Explain why, and explain why the shirt looks black in blue light. (3 marks)","marking_style":"points","scheme":{"max":6,"points":["(a) magnification = image height ÷ object height = 5.0 ÷ 2.0","(a) 2.5","(b) Real","(c) The shirt reflects red light and absorbs all other colours (wavelengths) in white light","(c) Blue light contains no red light for the shirt to reflect","(c) The blue light is absorbed, so no light is reflected and the shirt looks black"],"guidance":"In (a), magnification has no unit; do not penalise one being given."},"ao_marks":{"AO1":4,"AO2":2},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":11},{"topic":"Magnetism and Electromagnetism","subtopic":"Electromagnetism and the motor effect","spec_ref":"4.7.2.1-4.7.2.4","command_word":"explain","difficulty":"higher","total_marks":9,"question_text":"This question is about the magnetic effect of a current.\n\n(a) Describe the magnetic field around a long straight wire carrying a current. (2 marks)\n\n(b) A wire of length 0.050 m carries a current of 3.0 A. It is at right angles to a magnetic field of flux density 0.40 T.\n\nforce = magnetic flux density × current × length\n\nCalculate the force on the wire. Show your working. (2 marks)\n\n(c) Give two ways of reversing the direction of the force on the wire. (2 marks)\n\n(d) Explain how a simple dc electric motor keeps turning in the same direction. (3 marks)","marking_style":"points","scheme":{"max":9,"points":["(a) Concentric circles around the wire (in a plane at right angles to it)","(a) The field is stronger closer to the wire / the direction is given by the right-hand grip rule and reverses if the current reverses","(b) F = BIl = 0.40 × 3.0 × 0.050","(b) 0.060 N","(c) Reverse the direction of the current","(c) Reverse the direction of the magnetic field (swap the poles)","(d) The current in the two sides of the coil is in opposite directions, so the forces on them are in opposite directions","(d) This produces a turning effect (moment) on the coil","(d) A split-ring commutator reverses the current in the coil every half turn, so the coil keeps turning the same way"],"guidance":"In (c), reversing both together scores 0. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":6,"AO2":3},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":12},{"topic":"Magnetism and Electromagnetism","subtopic":"Induced potential, generators and transformers","spec_ref":"4.7.3.4","command_word":"calculate","difficulty":"higher","total_marks":7,"question_text":"A mains adapter contains a step-down transformer. The primary coil is connected to 230 V and has 2000 turns. The output potential difference is 11.5 V.\n\npotential difference across primary ÷ potential difference across secondary = number of turns on primary ÷ number of turns on secondary\npotential difference across primary × current in primary = potential difference across secondary × current in secondary\n\n(a) Calculate the number of turns on the secondary coil. Show your working. (2 marks)\n\n(b) The current in the secondary coil is 2.0 A. Assume the transformer is 100% efficient. Calculate the current in the primary coil. Show your working. (2 marks)\n\n(c) Explain why a transformer will not work if it is connected to a direct current (dc) supply. (3 marks)","marking_style":"points","scheme":{"max":7,"points":["(a) Ns = Np × Vs ÷ Vp = 2000 × 11.5 ÷ 230","(a) 100 turns","(b) Ip = Vs × Is ÷ Vp = 11.5 × 2.0 ÷ 230","(b) 0.10 A","(c) An alternating current in the primary coil produces a changing magnetic field in the iron core","(c) The changing magnetic field passes through the secondary coil","(c) This induces an alternating potential difference across the secondary coil","(c) A direct current produces a constant (unchanging) magnetic field, so no potential difference is induced"],"guidance":"In (c), award up to 3 marks from the 4 points. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3,"AO2":4},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":13},{"topic":"Space Physics","subtopic":"The solar system and the life cycle of a star","spec_ref":"4.8.1.2","command_word":"describe","difficulty":"higher","total_marks":6,"question_text":"Describe the life cycle of a star much more massive than the Sun, from its formation to the end of its life. Include how elements are formed during its life cycle.\n\n(6 marks)","marking_style":"levels","scheme":{"levels":[{"level":3,"marks":[5,6],"descriptor":"A detailed, correctly ordered description of every stage from nebula to neutron star or black hole, including how elements up to iron and heavier than iron are formed."},{"level":2,"marks":[3,4],"descriptor":"A description of most stages in the correct order, with some reference to the formation of elements."},{"level":1,"marks":[1,2],"descriptor":"Some stages named, possibly in the wrong order, with little detail."}],"indicative":["A star forms from a cloud of dust and gas (nebula), pulled together by gravity","This forms a protostar; it heats up as it gets denser","When it is hot enough, hydrogen nuclei fuse to form helium: fusion starts and it becomes a main sequence star","On the main sequence the outward force (pressure) from fusion energy balances the inward pull of gravity, so it is stable for a long time","When the hydrogen runs out, it swells to become a red super giant","In the red super giant, fusion forms heavier elements, up to iron","It explodes as a supernova","Elements heavier than iron are formed in the supernova, and the explosion spreads elements throughout the universe","What is left becomes a neutron star or, if the mass is great enough, a black hole"],"guidance":"Level 3 needs the stages in the correct order and both iron and heavier-than-iron element formation. Describing the Sun's life cycle (white dwarf) instead loses access to Level 3."},"ao_marks":{"AO1":6},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":14},{"topic":"Space Physics","subtopic":"Red-shift and the Big Bang","spec_ref":"4.8.2","command_word":"explain","difficulty":"higher","total_marks":4,"question_text":"This question is about red-shift.\n\n(a) What is red-shift? (1 mark)\n\n(b) Explain how observations of red-shift provide evidence for the Big Bang theory. (3 marks)","marking_style":"points","scheme":{"max":4,"points":["(a) An observed increase in the wavelength of light from distant galaxies (shifted towards the red end of the spectrum)","(b) Light from almost all distant galaxies is red-shifted, so they are moving away from us","(b) The further away the galaxy, the greater the red-shift, so the faster it is moving away","(b) So the universe is expanding","(b) Which suggests it began from a very small, extremely hot and dense region (the Big Bang)"],"guidance":"In (b), award up to 3 marks from the 4 points."},"ao_marks":{"AO1":4},"spag_marks":0,"paper_ref":"aqa-8463-h-p2-mock1","paper_number":15}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'AQA', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Physics'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

commit;
